function random "Pseudo random number generator"
  extends Modelica.Icons.Function;

  input Integer seedIn[3]
    "Integer vector defining random number sequence, e.g., {23,87,187}";
  output Real x "Random number between 0 and 1";
  output Integer seedOut[3]
    "Modified seed to be used for next call of random()";
algorithm
  seedOut[1] := rem((171*seedIn[1]), 30269);
  seedOut[2] := rem((172*seedIn[2]), 30307);
  seedOut[3] := rem((170*seedIn[3]), 30323);
  // zero is a poor seed, therefore substitute 1;
  if seedOut[1] == 0 then
    seedOut[1] := 1;
  end if;
  if seedOut[2] == 0 then
    seedOut[2] := 1;
  end if;
  if seedOut[3] == 0 then
    seedOut[3] := 1;
  end if;
  x := rem((seedOut[1]/30269.0 + seedOut[2]/30307.0 + seedOut[3]/30323.0), 1.0);
  
end random

function powerOfJ "Internal function to compute j^k for any integer"
    input Integer k;
    output Complex x;
  protected
    Integer m=mod(k,4);
  algorithm
   x:=if m==0 then Complex(1) elseif m==1 then j elseif m==2 then Complex(-1) else -j;
   
  end powerOfJ

function address "Compute memory address"
                extends Modelica.Icons.Function;
                input Integer n_addr;
                input L addr[n_addr];
                output Integer int_addr;
      protected
                L addr_bit;
              algorithm
                int_addr := 1;
                for i in 1:n_addr loop
                  addr_bit := T.X01Table[addr[i]];
                  if addr_bit == L.'1' then
                     int_addr := int_addr + integer(2^(i-1));
                  elseif addr_bit == L.'X' then
                     int_addr := 0;
                     break;
                  end if;
                end for;
              end address

function getMemory "Get Memory"
                extends Modelica.Icons.Function;
                input String filename;
                input Integer n_addr "Addr width";
                input Integer n_data "Data width";
                output L m[integer(2^n_addr),n_data] "Memory with data, lowest bit on left side";
                output String data;
                output Integer bit;
              algorithm
                for i in 1:(2^n_addr) loop
                  data := Modelica.Utilities.Streams.readLine(filename, integer(i));
                  for j in 1:n_data loop
                    bit := Modelica.Utilities.Strings.scanInteger(data, (2*j-1));
                    if bit == 1 then
                      m[integer(i),j] := L.'1';
                    elseif bit == 0 then
                      m[integer(i),j] := L.'0';
                    else
                      m[integer(i),j] := L.'X';
                    end if;
                  end for;
                end for;
              end getMemory

