  sig1[2] := -1.0;
  sig1[3] :=  1.0;
  sig1[4] := -1.0;
  sig2[1] :=  1.0;
  sig2[2] :=  1.0;
  sig2[3] := -1.0;
  sig2[4] := -1.0;

  if (p1 < 0) then
