      x4[iknt] := -a4[i]/2.0+tmp;
      iknt     := iknt+1;
      x4[iknt] := -a4[i]/2.0-tmp;
    end if;
  end for;
  jknt := 0;
  for j in 1:iknt loop
    if (x4[j] > 0) then
