if (Spice3.Internal.SpiceRoot.useInitialConditions())
             and (in_m.m_dICVDSIsGiven > 0.5) then
          int_c.m_vds := in_m_type * in_m.m_dICVDS

if (Spice3.Internal.SpiceRoot.useInitialConditions())
             and (in_m.m_dICVGSIsGiven > 0.5) then
          int_c.m_vgs := in_m_type * in_m.m_dICVGS

