function FCNq_sum_limit "Internal limitation function"
    extends Modelica.Icons.Function;
    input SI.Voltage q_sum;
    input SI.Voltage q_sum_ltf;
    input SI.Voltage v_pos;
    input SI.Voltage v_neg;
    input SI.Voltage vcp;
    input SI.Voltage vcm;
    output SI.Voltage result;

  algorithm
    if q_sum > v_pos - vcp and q_sum_ltf >= v_pos - vcp then
      result := v_pos - vcp;
    elseif q_sum < v_neg + vcm and q_sum_ltf <= v_neg + vcm then
      result := v_neg + vcm;
    else
      result := q_sum;
    end if;
    return;
    
  end FCNq_sum_limit

function FCNiout_limit "Internal limitation function"
    extends Modelica.Icons.Function;
    input SI.Voltage v_source;
    input SI.Voltage v_out;
    input SI.Resistance Rout;
    input SI.Current Imaxsi_val;
    input SI.Current Imaxso_val;
    output SI.Current result;

  algorithm
    if v_out > v_source + Rout*Imaxsi_val then
      result := Imaxsi_val;
    elseif v_out < v_source - Rout*Imaxso_val then
      result := -Imaxso_val;
    else
      result := (v_out - v_source)/Rout;
    end if;
    return;
    
  end FCNiout_limit

function exlin2 "Exponential function linearly continued for x < MinExp and x > Maxexp"
          extends Modelica.Icons.Function;
          input Real x;
          input Real Minexp;
          input Real Maxexp;
          output Real z;
        algorithm
          z := if x < Minexp then exp(Minexp)*(1 + x - Minexp) else exlin(x, Maxexp);
        end exlin2

function exlin "Exponential function linearly continued for x > Maxexp"
          extends Modelica.Icons.Function;
          input Real x;
          input Real Maxexp;
          output Real z;
        algorithm
          z := if x > Maxexp then exp(Maxexp)*(1 + x - Maxexp) else exp(x);
        end exlin

function powlin "Power function (1 - x)^(-y) linearly continued for x > 0 (provided y = const.)"
          extends Modelica.Icons.Function;
          input Real x;
          input Real y;
          output Real z;
        algorithm
          z := if x > 0 then 1 + y*x else pow(1 - x, -y);
        end powlin

function pow "Just a helper function for x^y in order that a symbolic engine can apply some transformations more easily"
          extends Modelica.Icons.Function;
          input Real x;
          input Real y;
          output Real z;
        algorithm
          z := x^y;
        end pow

function brushVoltageDrop "Voltage drop of carbon brushes"
  extends Modelica.Icons.Function;
  input Machines.Losses.BrushParameters brushParameters "Brush loss parameters";
  input SI.Current i "Actual current";
  output SI.Voltage v "Voltage drop";
algorithm
  if (brushParameters.V <= 0) then
    v := 0;
  else
    v := if (i > +brushParameters.ILinear) then +brushParameters.V else
      if (i < -brushParameters.ILinear) then -brushParameters.V else
      brushParameters.V*i/brushParameters.ILinear;
  end if;
  
end brushVoltageDrop

function activePower
  "Calculate active power of voltage and current input"
  import Modelica.Constants.pi;
  extends Modelica.Icons.Function;
  input SI.Voltage v[m] "Phase voltages";
  input SI.Current i[m] "Phase currents";
  output SI.Power p "Active power";
protected
  constant Integer m=3 "Number of phases";
  SI.Voltage v_[2] "Voltage space phasor";
  SI.Current i_[2] "Current space phasor";
algorithm
  v_ := zeros(2);
  i_ := zeros(2);
  for k in 1:m loop
    v_ := v_ + 2/m*{+cos((k - 1)/m*2*pi),+sin(+(k - 1)/m*2*pi)}*v[k];
    i_ := i_ + 2/m*{+cos((k - 1)/m*2*pi),+sin(+(k - 1)/m*2*pi)}*i[k];
  end for;
  p := m/2*(+v_[1]*i_[1] + v_[2]*i_[2]);
  
end activePower

function FromPolar "Converts a space phasor from polar coordinates"
  extends Modelica.Icons.Function;
  input Real absolute "Magnitude of space phasor";
  input SI.Angle angle "Angle of space phasor";
  output Real x[2] "Real and imaginary part of space phasor";
protected
  constant Real small=Modelica.Constants.small;
algorithm
  x := absolute*{cos(angle),sin(angle)};
  
end FromPolar

function FromSpacePhasor
  "Conversion from space phasor and zero sequence component to polyphase"
  import Modelica.Constants.pi;
  extends Modelica.Icons.Function;
  input Real x[2] "Space phasor";
  input Real x0 "Zero sequence component";
  input Integer m "Number of phases";
  output Real y[m] "Polyphase output";
protected
  SI.Angle phi[m]=
      Modelica.Electrical.Polyphase.Functions.symmetricOrientation(m);
  Real InverseTransformation[m, 2]={{+cos(-phi[k]),-sin(-phi[k])}
      for k in 1:m};

algorithm
  y := fill(x0, m) + InverseTransformation*x;

  
end FromSpacePhasor

function quasiRMS "Calculate quasi-RMS value of input"
  extends Modelica.Icons.Function;
  import Modelica.Constants.pi;
  input Real x[3];
  output Real y;
protected
  Integer m=size(x, 1) "Number of phases";
  SI.Angle phi[m]=
      Modelica.Electrical.Polyphase.Functions.symmetricOrientation(m);
  Real TransformationMatrix[2, m]=2/m*{+cos(+phi),+sin(+phi)};
  Real h[2]=TransformationMatrix*x;
algorithm
  y := sqrt(h[1]^2 + h[2]^2)/sqrt(2);
  
end quasiRMS

function Rotator "Rotates space phasor"
  extends Modelica.Icons.Function;
