             if Re < Re2 then
                Re := interpolateInRegion2(Re, Re1, Re2, Delta, lambda2);
             end if;
          end if;

          // Determine mass flow rate
          m_flow := crossArea/diameter*mu*(if dp >= 0 then Re else -Re);
                  
        end massFlowRate_dp

