else
              // d  < d2n(p23, T) and T > data.TLIMIT1
              region := 2

// below critical, check for regions 1, 2, 3 or 4
          elseif (d > rhol_T(T)) then
            // either 1 or 3
            if T < data.TLIMIT1 then
              region := 1

